package main

import "fmt"

func main() {
	var N int
	fmt.Scan(&N)

	direita := make([]int, 61)
	esquerda := make([]int, 61)

	for i := 0; i < N; i++ {
		var M int
		var L string

		fmt.Scan(&M, &L)

		if L == "D" {
			direita[M]++
		} else {
			esquerda[M]++
		}
	}

	pares := 0

	for tamanho := 30; tamanho <= 60; tamanho++ {
		if direita[tamanho] < esquerda[tamanho] {
			pares += direita[tamanho]
		} else {
			pares += esquerda[tamanho]
		}
	}

	fmt.Println(pares)
}
